import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { checkSkillsIndex, collectSkillsIndex } from "../../scripts/sync-skills-index.mjs";

const appDir = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const repoRoot = path.dirname(appDir);
const outputPath = path.join(appDir, "lib/skills-bundle.js");

function renderBundle() {
  if (!checkSkillsIndex(repoRoot)) {
    throw new Error(
      "repo-index.json 与 .skills 不一致，请先运行 node scripts/sync-skills-index.mjs",
    );
  }

  const index = collectSkillsIndex(repoRoot);
  const entries = index.files
    .map((virtualPath) => {
      const content = readFileSync(path.join(repoRoot, virtualPath.slice(1)), "utf8");
      return `    ${JSON.stringify(virtualPath)}: ${JSON.stringify(content)},`;
    })
    .join("\n");

  return `// Generated by web/scripts/sync-skills-bundle.mjs. Do not edit.
export const skillsBundle = {
  root: ${JSON.stringify(index.root)},
  files: {
${entries}
  },
};
`;
}

function main() {
  const rendered = renderBundle();
  const existing = readFileSyncIfExists(outputPath);

  if (process.argv.includes("--check")) {
    if (existing !== rendered) {
      console.error("web/lib/skills-bundle.js 未生成或已过期");
      process.exitCode = 1;
      return;
    }
    console.log("skills-bundle.js 已同步");
    return;
  }

  if (existing !== rendered) {
    writeFileSync(outputPath, rendered);
  }
  console.log("已写入 web/lib/skills-bundle.js");
}

function readFileSyncIfExists(filePath) {
  try {
    return readFileSync(filePath, "utf8");
  } catch {
    return undefined;
  }
}

main();
